from taf.rfrl.procedures.resources.python.bts.components.component_collection import ComponentCollection


class Bts:
    """ Represents generic Base Transceiver Station. """

    _MISSING_IMPLEMENTATION_ERROR_MSG = '{} class has missing implementation of {}'

    def __init__(self,
                 ip: str,
                 port: int,
                 user_name: str,
                 password: str):
        """
        :param ip: IP address of BTS to which API connection should open
        :param port: port number on which API connection should open
        :param user_name: login used for authentication during opening API connection
        :param password: password used for authentication during opening API connection
        """
        self._ip = ip
        self._port = port
        self._user_name = user_name
        self._password = password
        self._ran = None
        self._mode = None

    @property
    def node(self) -> str:
        """ Returns type of Node B for this BTS, i.e. 'gNB'. """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, 'node'))

    @property
    def mode(self) -> str:
        """ Returns mode in which BTS is operating, i.e. 'NSA'. """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, 'mode'))

    @property
    def rmods(self) -> ComponentCollection:
        """ Returns all RMODs connected to this BTS. """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, 'rmods'))

    @property
    def cells(self) -> ComponentCollection:
        """ Returns all Cells configured on this BTS. """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, 'cells'))

    def connect(self):
        """ Opens API connections to this BTS. """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, self.connect.__name__))

    def load(self):
        """ Loads all components currently connected to this BTS. """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, self.load.__name__))

    def disconnect(self):
        """ Closes API connections to this BTS. """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, self.disconnect.__name__))

    def check_if_reachable(self, delay: int = 0, timeout: int = 5):
        """
        Checks whether this BTS is reachable via HTTP.
        :param delay: time (in seconds) to wait before checking if reachable;
                      defaults to 0 (no delay)
        :param timeout: time (in seconds) for BTS to become reachable;
                        defaults to 5
        :raises ResultError: if BTS doesn't become reachable before the timeout
        """
        raise NotImplementedError(self._MISSING_IMPLEMENTATION_ERROR_MSG.format(
            self.__class__.__name__, self.check_if_reachable.__name__))
